/******************CREATE LT CLEAN PROCEDURE********************/ CREATE PROCEDURE "DA_CA_LT_CLEAN" (IN SchemaName VARCHAR(100)) LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER  AS BEGIN     DECLARE ROWCNT INTEGER;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_LOGISTICR_REGRESSION' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'CALL SYS.AFLLANG_WRAPPER_PROCEDURE_DROP(''' || :SchemaName || ''', ''DA_CA_PAL_LOGISTICR_REGRESSION'')';     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_LOGISTICR_FORECAST' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'CALL SYS.AFLLANG_WRAPPER_PROCEDURE_DROP(''' || :SchemaName || ''', ''DA_CA_PAL_LOGISTICR_FORECAST'')';     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_LT_CREATE_WRAPPER' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP PROCEDURE "DA_CA_PAL_LT_CREATE_WRAPPER"';     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMP_DA_CA_LOGISTICR_DATA_TABLE' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #TEMP_DA_CA_LOGISTICR_DATA_TABLE;     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMP_DA_CA_LOGISTICR_PREDICT_DATA_TABLE' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #TEMP_DA_CA_LOGISTICR_PREDICT_DATA_TABLE;     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMP_DA_CA_PAL_CONTROL_TABLE_FORECAST' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #TEMP_DA_CA_PAL_CONTROL_TABLE_FORECAST;     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#TEMP_DA_CA_PAL_COEFFICIENT_TABLE' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #TEMP_DA_CA_PAL_COEFFICIENT_TABLE;     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."PROCEDURES" WHERE PROCEDURE_NAME='DA_CA_PAL_LT_PREDICTION' AND SCHEMA_NAME=:SchemaName;     IF ROWCNT>0 THEN         EXECUTE IMMEDIATE 'DROP PROCEDURE "DA_CA_PAL_LT_PREDICTION"';     END IF; END
